const { requireWithFallback } = require('./require-package');

const { SHOPIFY_ADMIN_API_VERSION } = requireWithFallback(
  require,
  '@synclistic/types',
  '../../types'
);

function normalizeShopDomain(value) {
  const rawValue = String(value || '').trim();
  if (!rawValue) {
    return null;
  }

  if (/^https?:\/\//i.test(rawValue)) {
    try {
      return new URL(rawValue).host.toLowerCase();
    } catch (error) {
      return null;
    }
  }

  const withoutPath = rawValue.split('/')[0];
  if (!withoutPath) {
    return null;
  }

  return withoutPath.toLowerCase();
}

function normalizeStoreIdentity(store) {
  if (!store) {
    return null;
  }

  if (typeof store === 'string') {
    return normalizeShopDomain(store);
  }

  return normalizeShopDomain(store.store_url || store.shop);
}

function buildAdminGraphqlUrl(store) {
  const shop = normalizeStoreIdentity(store);
  if (!shop) {
    throw new Error('Store URL is required');
  }

  return `https://${shop}/admin/api/${SHOPIFY_ADMIN_API_VERSION}/graphql.json`;
}

module.exports = {
  buildAdminGraphqlUrl,
  normalizeShopDomain,
  normalizeStoreIdentity
};
